begin;
drop trigger if exists aios_missions_audit_log on public.aios_missions;
drop trigger if exists aios_tasks_audit_log on public.aios_tasks;
drop trigger if exists aios_tool_invocations_audit_log on public.aios_tool_invocations;
drop trigger if exists aios_tool_invocations_authority_check on public.aios_tool_invocations;
create or replace function private.aios_audit_append() returns trigger language plpgsql security definer set search_path='' as $$ declare v_prev text; v_payload text; begin perform pg_advisory_xact_lock(hashtextextended(coalesce(new.organization_id::text,''),0)); select event_hash into v_prev from public.aios_audit_events where organization_id=new.organization_id order by created_at desc,id desc limit 1; new.previous_event_hash=coalesce(v_prev,'GENESIS:'||new.organization_id::text); v_payload=jsonb_build_object('id',new.id,'organization_id',new.organization_id,'actor_user_id',new.actor_user_id,'actor_type',new.actor_type,'agent_id',new.agent_id,'mission_id',new.mission_id,'task_id',new.task_id,'invocation_id',new.invocation_id,'event_type',new.event_type,'previous_state',new.previous_state,'new_state',new.new_state,'tool_name',new.tool_name,'risk_level',new.risk_level,'arguments_hash',new.arguments_hash,'result_hash',new.result_hash,'approval_id',new.approval_id,'created_at',new.created_at,'metadata',new.metadata,'previous_event_hash',new.previous_event_hash)::text||new.previous_event_hash; new.event_hash=encode(extensions.digest(v_payload,'sha256'),'hex'); return new; end; $$;
create or replace function private.aios_enforce_agent_authority() returns trigger language plpgsql security definer set search_path='' as $$ declare v_agent record; v_contract record; v_tool record; v_reason text; v_approval uuid; begin select a.id,a.organization_id,a.status into v_agent from public.aios_agents a where a.id=new.agent_id; if v_agent.id is null then raise exception 'agent not found'; end if; if v_agent.organization_id is distinct from new.organization_id then raise exception 'agent organization mismatch'; end if; if v_agent.status='suspended' then new.status='denied'; new.result=jsonb_build_object('kernel_reason','agent suspended'); return new; end if; select c.id,c.version,c.risk_level,c.allowed_tools into v_contract from public.aios_contracts c where c.agent_id=new.agent_id and c.organization_id=new.organization_id and c.is_active order by c.version desc limit 1; if v_contract.id is null then new.status='denied'; new.result=jsonb_build_object('kernel_reason','no active contract'); return new; end if; select t.id,t.tool_key,t.risk_level,t.is_enabled,t.status,t.requires_approval into v_tool from public.aios_tools t where t.tool_key=coalesce(new.tool_key,new.tool_name); if v_tool.id is null then new.status='denied'; new.result=jsonb_build_object('kernel_reason','unknown tool'); return new; end if; if not v_tool.is_enabled or v_tool.status<>'active' then new.status='denied'; new.result=jsonb_build_object('kernel_reason','tool disabled'); return new; end if; new.tool_key=v_tool.tool_key; new.tool_name=v_tool.tool_key; new.arguments=coalesce(new.arguments,'{}'::jsonb); new.arguments_hash=encode(extensions.digest(new.arguments::text,'sha256'),'hex'); if not(v_contract.allowed_tools ? v_tool.tool_key) then v_reason='tool not in active contract'; elsif public.aios_risk_rank(v_tool.risk_level)>public.aios_risk_rank(v_contract.risk_level) or public.aios_risk_rank(new.risk_level)>public.aios_risk_rank(v_contract.risk_level) then v_reason='risk exceeds contract ceiling'; elsif v_tool.requires_approval then v_reason='tool requires approval'; end if; if v_reason is not null then new.status='requires_approval'; new.result=coalesce(new.result,'{}'::jsonb)||jsonb_build_object('kernel_reason',v_reason,'contract_version',v_contract.version); insert into public.aios_approvals(organization_id,agent_id,task_id,invocation_id,action,risk_level,resource,reason,approval_reason,tool_key,arguments_hash,approval_version,status,expires_at) values(new.organization_id,new.agent_id,new.task_id,new.id,new.tool_key,new.risk_level,new.tool_key,v_reason,v_reason,v_tool.tool_key,new.arguments_hash,v_contract.version,'pending',now()+interval '30 minutes') returning id into v_approval; new.approval_id=v_approval; else new.authorization_version=v_contract.version; new.status='approved'; end if; return new; end; $$;
alter table public.aios_tool_invocations disable trigger trg_aios_invocation_status_guard; update public.aios_tool_invocations set status='succeeded' where status='completed'; update public.aios_tool_invocations set status='denied' where status='rejected'; alter table public.aios_tool_invocations enable trigger trg_aios_invocation_status_guard;
alter table public.aios_tasks disable trigger trg_aios_task_status_guard; update public.aios_tasks set status='completed' where status='done'; update public.aios_tasks set status='running' where status='active'; alter table public.aios_tasks enable trigger trg_aios_task_status_guard;
commit;
